from typing import Any

from core.sql_first.db import fetch_all_dict, fetch_one_dict, sql_connection


def _insert_one(sql: str, params: list[Any]) -> dict[str, Any]:
    with sql_connection() as conn:
        cur = conn.cursor()
        cur.execute(sql, params)
        row = cur.fetchone()
        cols = [d[0] for d in cur.description] if cur.description else []
        conn.commit()
        return dict(zip(cols, row)) if row else {}


def get_empresa_configuracion(empresa_id: int):
    return fetch_one_dict("SELECT EmpresaID,CatalogoLegalAmpliadoActivo,DiasAlertaDefault,Activo,FechaAlta,FechaActualizacion,UsuarioActualizacionID FROM dbo.Gobierno_EmpresaConfiguracion WHERE EmpresaID=?", [empresa_id])


def empresa_existe(empresa_id: int) -> bool:
    return fetch_one_dict("SELECT EmpresaID FROM dbo.Sistema_Empresas WHERE EmpresaID=?", [empresa_id]) is not None


def upsert_empresa_configuracion(empresa_id: int, activo: bool, dias: int | None, usuario_id: int):
    with sql_connection() as conn:
        cur=conn.cursor(); cur.execute("""UPDATE dbo.Gobierno_EmpresaConfiguracion SET CatalogoLegalAmpliadoActivo=?,DiasAlertaDefault=?,Activo=1,FechaActualizacion=SYSUTCDATETIME(),UsuarioActualizacionID=? WHERE EmpresaID=?; IF @@ROWCOUNT=0 INSERT INTO dbo.Gobierno_EmpresaConfiguracion(EmpresaID,CatalogoLegalAmpliadoActivo,DiasAlertaDefault,UsuarioActualizacionID) VALUES(?,?,?,?);""", [activo,dias,usuario_id,empresa_id,empresa_id,activo,dias,usuario_id]); conn.commit()
    return get_empresa_configuracion(empresa_id)


def list_personas(empresa_id: int | None=None):
    if empresa_id is None:
        return fetch_all_dict("SELECT * FROM dbo.Gobierno_Persona WHERE Activo=1 ORDER BY Nombre,ApellidoPaterno,PersonaID")
    return fetch_all_dict("""SELECT DISTINCT p.* FROM dbo.Gobierno_Persona p JOIN dbo.Gobierno_PersonaEmpresaRol r ON r.PersonaID=p.PersonaID AND r.Activo=1 WHERE p.Activo=1 AND r.EmpresaID=? ORDER BY p.Nombre,p.ApellidoPaterno,p.PersonaID""", [empresa_id])


def create_persona(data, usuario_id: int):
    return _insert_one("""INSERT INTO dbo.Gobierno_Persona(Nombre,ApellidoPaterno,ApellidoMaterno,RFC,CURP,FechaNacimiento,Nacionalidad,UsuarioActualizacionID) OUTPUT INSERTED.* VALUES(?,?,?,?,?,?,?,?)""", [data.get('nombre'),data.get('apellido_paterno'),data.get('apellido_materno'),data.get('rfc'),data.get('curp'),data.get('fecha_nacimiento'),data.get('nacionalidad'),usuario_id])


def create_vinculo(persona_id: int, data, usuario_id: int):
    return _insert_one("""INSERT INTO dbo.Gobierno_PersonaVinculo(PersonaID,UsuarioID,ClienteID,ProveedorID,ContactoClienteID,ContactoProveedorID,EsPrincipal,UsuarioAltaID) OUTPUT INSERTED.* VALUES(?,?,?,?,?,?,?,?)""", [persona_id,data.get('usuario_id'),data.get('cliente_id'),data.get('proveedor_id'),data.get('contacto_cliente_id'),data.get('contacto_proveedor_id'),data.get('es_principal',False),usuario_id])


def list_roles_catalogo():
    return fetch_all_dict("SELECT * FROM dbo.Gobierno_RolCorporativoCatalogo WHERE Activo=1 ORDER BY Nombre,RolCorporativoID")


def create_empresa_rol(empresa_id: int, data, usuario_id: int):
    return _insert_one("""INSERT INTO dbo.Gobierno_PersonaEmpresaRol(PersonaID,EmpresaID,RolCorporativoID,CargoDetalle,ParticipacionPct,Facultades,VigenteDesde,VigenteHasta,UsuarioAltaID) OUTPUT INSERTED.* VALUES(?,?,?,?,?,?,?,?,?)""", [data['persona_id'],empresa_id,data['rol_corporativo_id'],data.get('cargo_detalle'),data.get('participacion_pct'),data.get('facultades'),data.get('vigente_desde'),data.get('vigente_hasta'),usuario_id])


def list_tipos_documento():
    return fetch_all_dict("SELECT * FROM dbo.Gobierno_TipoDocumento WHERE Activo=1 ORDER BY Nombre,TipoDocumentoID")


def list_documentos(empresa_id: int):
    return fetch_all_dict("""SELECT d.*,td.Codigo TipoDocumentoCodigo,td.Nombre TipoDocumentoNombre,v.DocumentoVersionID,v.NumeroVersion,v.FechaEmision,v.FechaVencimiento,v.FechaVencimientoFuente,v.EstadoRevision,v.OCRConfianza FROM dbo.Gobierno_Documento d JOIN dbo.Gobierno_TipoDocumento td ON td.TipoDocumentoID=d.TipoDocumentoID OUTER APPLY(SELECT TOP 1 dv.* FROM dbo.Gobierno_DocumentoVersion dv WHERE dv.DocumentoID=d.DocumentoID ORDER BY dv.NumeroVersion DESC) v LEFT JOIN dbo.Gobierno_PersonaEmpresaRol pr ON pr.PersonaEmpresaRolID=d.PersonaEmpresaRolID WHERE d.Activo=1 AND (d.EmpresaID=? OR pr.EmpresaID=?) ORDER BY d.Titulo,d.DocumentoID""", [empresa_id,empresa_id])


def create_documento(data, usuario_id: int):
    with sql_connection() as conn:
        cur=conn.cursor(); cur.execute("""INSERT INTO dbo.Gobierno_Documento(TipoDocumentoID,PropietarioTipo,PersonaID,EmpresaID,PersonaEmpresaRolID,Titulo,UsuarioAltaID) OUTPUT INSERTED.* VALUES(?,?,?,?,?,?,?)""", [data['tipo_documento_id'],data['propietario_tipo'],data.get('persona_id'),data.get('empresa_id'),data.get('persona_empresa_rol_id'),data['titulo'],usuario_id]); row=cur.fetchone(); cols=[d[0] for d in cur.description]; doc=dict(zip(cols,row)); cur.execute("INSERT INTO dbo.Gobierno_DocumentoMovimiento(DocumentoID,TipoMovimiento,UsuarioID) VALUES(?,?,?)", [doc['DocumentoID'],'CREACION',usuario_id]); conn.commit(); return doc


def create_documento_version(documento_id: int, data, usuario_id: int):
    with sql_connection() as conn:
        cur=conn.cursor(); cur.execute("SELECT ISNULL(MAX(NumeroVersion),0)+1 FROM dbo.Gobierno_DocumentoVersion WITH (UPDLOCK,HOLDLOCK) WHERE DocumentoID=?", [documento_id]); numero=int(cur.fetchone()[0]); cur.execute("""INSERT INTO dbo.Gobierno_DocumentoVersion(DocumentoID,NumeroVersion,NombreArchivo,StorageKey,MimeType,TamanioBytes,SHA256,FechaEmision,FechaVencimiento,FechaVencimientoFuente,OCRTexto,OCRMetadataJSON,OCRConfianza,UsuarioAltaID) OUTPUT INSERTED.* VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", [documento_id,numero,data['nombre_archivo'],data['storage_key'],data.get('mime_type'),data.get('tamanio_bytes'),data['sha256'].lower(),data.get('fecha_emision'),data.get('fecha_vencimiento'),data.get('fecha_vencimiento_fuente'),data.get('ocr_texto'),data.get('ocr_metadata_json'),data.get('ocr_confianza'),usuario_id]); row=cur.fetchone(); cols=[d[0] for d in cur.description]; version=dict(zip(cols,row)); cur.execute("INSERT INTO dbo.Gobierno_DocumentoMovimiento(DocumentoID,DocumentoVersionID,TipoMovimiento,UsuarioID) VALUES(?,?,?,?)", [documento_id,version['DocumentoVersionID'],'NUEVA_VERSION',usuario_id]); conn.commit(); return version


def get_kardex(documento_id: int):
    return fetch_all_dict("SELECT * FROM dbo.Gobierno_DocumentoMovimiento WHERE DocumentoID=? ORDER BY FechaUTC DESC,MovimientoID DESC", [documento_id])


def list_vencimientos(empresa_id: int, dias: int):
    return fetch_all_dict("""SELECT d.DocumentoID,d.Titulo,td.Nombre TipoDocumento,v.DocumentoVersionID,v.FechaVencimiento,DATEDIFF(DAY,CAST(GETDATE() AS date),v.FechaVencimiento) DiasRestantes FROM dbo.Gobierno_Documento d JOIN dbo.Gobierno_TipoDocumento td ON td.TipoDocumentoID=d.TipoDocumentoID JOIN dbo.Gobierno_DocumentoVersion v ON v.DocumentoID=d.DocumentoID LEFT JOIN dbo.Gobierno_PersonaEmpresaRol pr ON pr.PersonaEmpresaRolID=d.PersonaEmpresaRolID WHERE d.Activo=1 AND v.EstadoRevision='VALIDADO' AND v.NumeroVersion=(SELECT MAX(v2.NumeroVersion) FROM dbo.Gobierno_DocumentoVersion v2 WHERE v2.DocumentoID=d.DocumentoID) AND (d.EmpresaID=? OR pr.EmpresaID=?) AND v.FechaVencimiento>=CAST(GETDATE() AS date) AND v.FechaVencimiento<=DATEADD(DAY,?,CAST(GETDATE() AS date)) ORDER BY v.FechaVencimiento,d.DocumentoID""", [empresa_id,empresa_id,dias])


def list_alerta_reglas(empresa_id: int):
    return fetch_all_dict("SELECT * FROM dbo.Gobierno_AlertaRegla WHERE Activo=1 AND (EmpresaID=? OR EmpresaID IS NULL) ORDER BY DiasAntes DESC,AlertaReglaID", [empresa_id])


def create_alerta_regla(empresa_id: int, data, usuario_id: int):
    return _insert_one("""INSERT INTO dbo.Gobierno_AlertaRegla(EmpresaID,TipoDocumentoID,UsuarioObjetivoID,DiasAntes,Canal,UsuarioAltaID) OUTPUT INSERTED.* VALUES(?,?,?,?,?,?)""", [empresa_id,data.get('tipo_documento_id'),data.get('usuario_objetivo_id'),data['dias_antes'],data['canal'],usuario_id])

from fastapi import APIRouter, Depends, HTTPException, Query

from core.rbac_helper_sql import has_full_access
from core.security import get_current_user
from . import repository as repo
from .schemas import AlertaReglaCreate,DocumentoCreate,DocumentoVersionCreate,EmpresaConfiguracionUpdate,PersonaCreate,PersonaEmpresaRolCreate,PersonaVinculoCreate

router=APIRouter(prefix='/catalogo-ampliado',tags=['Catalogo Ampliado'])


def _usuario_id(user: dict) -> int:
    value=user.get('_sql_usuario_id') or user.get('UsuarioID')
    if value is None:
        raise HTTPException(status_code=403,detail='Usuario SQL canonico no resuelto')
    return int(value)


def _gobierno_admin(current_user: dict=Depends(get_current_user)) -> dict:
    if not has_full_access(current_user):
        raise HTTPException(status_code=403,detail='Sin permisos de gobierno corporativo')
    _usuario_id(current_user)
    return current_user


def _assert_empresa(empresa_id: int, require_active: bool=True) -> None:
    if not repo.empresa_existe(empresa_id):
        raise HTTPException(status_code=404,detail='Empresa no encontrada')
    if require_active:
        cfg=repo.get_empresa_configuracion(empresa_id)
        if not cfg or not cfg.get('CatalogoLegalAmpliadoActivo') or not cfg.get('Activo'):
            raise HTTPException(status_code=409,detail='Catalogo legal ampliado no activo para esta empresa')


@router.get('/empresas/{empresa_id}/configuracion')
def empresa_configuracion(empresa_id:int,current_user:dict=Depends(_gobierno_admin)):
    _assert_empresa(empresa_id,False); return {'success':True,'data':repo.get_empresa_configuracion(empresa_id)}

@router.put('/empresas/{empresa_id}/configuracion')
def actualizar_configuracion(empresa_id:int,body:EmpresaConfiguracionUpdate,current_user:dict=Depends(_gobierno_admin)):
    _assert_empresa(empresa_id,False); return {'success':True,'data':repo.upsert_empresa_configuracion(empresa_id,body.catalogo_legal_ampliado_activo,body.dias_alerta_default,_usuario_id(current_user))}

@router.get('/personas')
def personas(empresa_id:int|None=Query(default=None),current_user:dict=Depends(_gobierno_admin)):
    if empresa_id is not None: _assert_empresa(empresa_id)
    return {'success':True,'data':repo.list_personas(empresa_id)}

@router.post('/personas',status_code=201)
def crear_persona(body:PersonaCreate,current_user:dict=Depends(_gobierno_admin)):
    return {'success':True,'data':repo.create_persona(body.model_dump(),_usuario_id(current_user))}

@router.post('/personas/{persona_id}/vinculos',status_code=201)
def crear_vinculo(persona_id:int,body:PersonaVinculoCreate,current_user:dict=Depends(_gobierno_admin)):
    data=body.model_dump(); targets=[data.get(k) for k in ('usuario_id','cliente_id','proveedor_id','contacto_cliente_id','contacto_proveedor_id')]
    if sum(v is not None for v in targets)!=1: raise HTTPException(status_code=422,detail='Debe indicarse exactamente un destino canonico')
    return {'success':True,'data':repo.create_vinculo(persona_id,data,_usuario_id(current_user))}

@router.get('/roles-corporativos')
def roles(current_user:dict=Depends(_gobierno_admin)):
    return {'success':True,'data':repo.list_roles_catalogo()}

@router.post('/empresas/{empresa_id}/roles',status_code=201)
def asignar_rol(empresa_id:int,body:PersonaEmpresaRolCreate,current_user:dict=Depends(_gobierno_admin)):
    _assert_empresa(empresa_id)
    if body.vigente_desde and body.vigente_hasta and body.vigente_hasta<body.vigente_desde: raise HTTPException(status_code=422,detail='vigente_hasta no puede ser anterior a vigente_desde')
    return {'success':True,'data':repo.create_empresa_rol(empresa_id,body.model_dump(),_usuario_id(current_user))}

@router.get('/tipos-documento')
def tipos_documento(current_user:dict=Depends(_gobierno_admin)):
    return {'success':True,'data':repo.list_tipos_documento()}

@router.get('/empresas/{empresa_id}/documentos')
def documentos(empresa_id:int,current_user:dict=Depends(_gobierno_admin)):
    _assert_empresa(empresa_id); return {'success':True,'data':repo.list_documentos(empresa_id)}

@router.post('/empresas/{empresa_id}/documentos',status_code=201)
def crear_documento(empresa_id:int,body:DocumentoCreate,current_user:dict=Depends(_gobierno_admin)):
    _assert_empresa(empresa_id); data=body.model_dump(); tipo=data['propietario_tipo']
    if tipo=='EMPRESA': data.update(empresa_id=empresa_id,persona_id=None,persona_empresa_rol_id=None)
    elif tipo=='PERSONA':
        if not data.get('persona_id'): raise HTTPException(status_code=422,detail='persona_id requerido')
        data.update(empresa_id=None,persona_empresa_rol_id=None)
    else:
        if not data.get('persona_empresa_rol_id'): raise HTTPException(status_code=422,detail='persona_empresa_rol_id requerido')
        data.update(empresa_id=None,persona_id=None)
    return {'success':True,'data':repo.create_documento(data,_usuario_id(current_user))}

@router.post('/documentos/{documento_id}/versiones',status_code=201)
def crear_version(documento_id:int,body:DocumentoVersionCreate,current_user:dict=Depends(_gobierno_admin)):
    if body.fecha_emision and body.fecha_vencimiento and body.fecha_vencimiento<body.fecha_emision: raise HTTPException(status_code=422,detail='fecha_vencimiento invalida')
    return {'success':True,'data':repo.create_documento_version(documento_id,body.model_dump(),_usuario_id(current_user))}

@router.get('/documentos/{documento_id}/kardex')
def kardex(documento_id:int,current_user:dict=Depends(_gobierno_admin)):
    return {'success':True,'data':repo.get_kardex(documento_id)}

@router.get('/empresas/{empresa_id}/vencimientos')
def vencimientos(empresa_id:int,dias:int=Query(default=30,ge=0,le=3650),current_user:dict=Depends(_gobierno_admin)):
    _assert_empresa(empresa_id); return {'success':True,'en_dias':dias,'data':repo.list_vencimientos(empresa_id,dias)}

@router.get('/empresas/{empresa_id}/alertas/reglas')
def reglas_alerta(empresa_id:int,current_user:dict=Depends(_gobierno_admin)):
    _assert_empresa(empresa_id); return {'success':True,'data':repo.list_alerta_reglas(empresa_id)}

@router.post('/empresas/{empresa_id}/alertas/reglas',status_code=201)
def crear_regla_alerta(empresa_id:int,body:AlertaReglaCreate,current_user:dict=Depends(_gobierno_admin)):
    _assert_empresa(empresa_id); return {'success':True,'data':repo.create_alerta_regla(empresa_id,body.model_dump(),_usuario_id(current_user))}
